let _GEO_INE_IDX = null;
function _geoIneInit(){
  if(_GEO_INE_IDX) return _GEO_INE_IDX;
  const byE = new Map(), byEM = new Map(), byM = new Map(), byEP = new Map(), byP = new Map();
  const ambM = new Set(), ambEP = new Set(), ambP = new Set();
  const normE = fe => (fe === 'vargas' ? 'la guaira' : fe);

  GEO_INE_EMP.forEach(s => {
    const [e, m, p] = s.split('|');
    const fe = fold(e), fm = fold(m), fp = fold(p);
    if(!byE.has(fe)) byE.set(fe, e);
    const emk = fe + '|' + fm;
    if(!byEM.has(emk)) byEM.set(emk, [e, m]);

    if(ambM.has(fm)){}
    else if(byM.has(fm) && fold(byM.get(fm)[0]) !== fe){ byM.delete(fm); ambM.add(fm); }
    else byM.set(fm, [e, m]);

    const epk = fe + '|' + fp;
    if(ambEP.has(epk)){}
    else if(byEP.has(epk) && fold(byEP.get(epk)[1]) !== fm){ byEP.delete(epk); ambEP.add(epk); }
    else byEP.set(epk, [e, m, p]);

    if(ambP.has(fp)){}
    else if(byP.has(fp)){ byP.delete(fp); ambP.add(fp); }
    else byP.set(fp, [e, m, p]);
  });
  if(byE.has('la guaira') && !byE.has('vargas')) byE.set('vargas', byE.get('la guaira'));
  if(byE.has('vargas') && !byE.has('la guaira')) byE.set('la guaira', byE.get('vargas'));

  _GEO_INE_IDX = { byE, byEM, byM, byEP, byP, normE };
  return _GEO_INE_IDX;
}

function geoIneInfer({ estado, mun, parr, com }){
  const idx = _geoIneInit();
  let e = estado || '', m = mun || '', p = parr || '';
  const fe = idx.normE(fold(e)), fm = fold(m), fp = fold(p), fc = fold(com || '');

  if(e && !m && p){
    const hit = idx.byEP.get(fe + '|' + fp);
    if(hit) m = hit[1];
  } else if(!e && !m && p){
    const hit = idx.byP.get(fp);
    if(hit){ e = hit[0]; m = hit[1]; }
  } else if(!e && m){
    const hit = idx.byM.get(fm);
    if(hit) e = hit[0];
  }

  if((!e || !m || !p) && fc){
    let empIdx = (fe && GEO_INE_COM[fe + '|' + fc] != null) ? GEO_INE_COM[fe + '|' + fc] : GEO_INE_COM[fc];
    if(empIdx != null){
      const [ie, im, ip] = GEO_INE_EMP[empIdx].split('|');
      if(!e) e = ie;
      if(!m && (!fe || fold(ie) === fe)) m = im;
      if(!p && (!fm || fold(im) === fm) && (!fe || fold(ie) === fe)) p = ip;
    }
  }
  return { estado: e, mun: m, parr: p, com: com || '' };
}